const TIME_LIMIT: int = 1300;
const SOURCE_LIMIT: int = 1180; // no source timeout; local estimate with trailing bullets
const TH18_BALL2: int = 432;    // source etSprite type 5, color 4

// GirlA01_at 416-418: birth ANIM skipped by policy; WAIT 90 then VELTIME 100 to 3.2.
// Bullets keep their 0.5 launch speed for 90 frames, then ramp linearly along the same angle.
xformdef GIRL_BULLET {
    wait(90);
    step_speed(3.2fx, 100 + 65536 * EASE_LINEAR);
}

async sub girl_fire() {
    // GirlA01_at 400: wait(10); 401-419 etNew/etAim(0,0)/etSprite(5,4)/
    // etCount(rank count,1)/etAngle/etSpeed(0.5,1.0, M=1) and etEx(416-418).
    wait(10);
    var rank: int = global(GVAR_RANK);
    var n: int = 1;
    if rank >= 2 { n = 3; }
    var cooldown: int = 60;       // source 432-441: E120, N/H60, L50
    if rank == 0 { cooldown = 120; }
    if rank == 3 { cooldown = 50; }
    for outer in 0..10 {          // source $A=10
        for inner in 0..10 {      // source $B=10
            // 426 etOffsetRad: RANDRAD, then RANDF2*32.
            var oa: angle = rand(65536) as angle;
            var u: fx = (rand(65536)-32768) as fx;
            var od: fx = (u / 32768) * 32fx;
            var sx: fx = $self_x + od * cos(oa);
            var sy: fx = $self_y + od * sin(oa);
            // 427 etAngle: RANDF2*2deg base offset, 60deg route spacing; mode 0 aimed fan.
            var alpha: angle = (rand(729)-364) as angle;
            var aim: angle = atan2($player_y - sy, $player_x - sx);
            _ = fire(TH18_BALL2, 4, sx, sy, 0.5fx, aim + alpha, GIRL_BULLET, none);
            if n == 3 {
                _ = fire(TH18_BALL2, 4, sx, sy, 0.5fx, aim + alpha - 60deg, GIRL_BULLET, none);
                _ = fire(TH18_BALL2, 4, sx, sy, 0.5fx, aim + alpha + 60deg, GIRL_BULLET, none);
            }
            wait(2);              // 429
        }
        wait(cooldown);           // 441 wait([-1])
    }
}

async sub girl_main() {
    // GirlA01 383-384: source setHurtbox(24,24), setHitbox(16,16); ordinary circle uses half width.
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    // 385 moveVel(pi/2, 0.8); 386 async GirlA01_at.
    move_vel(0, 90deg, 0.8fx, EASE_LINEAR);
    spawn girl_fire();
    // 387-388 wait 180, then moveVelTime(120, mode 1 = t^2, ANGLE_PLAYER, 1.2).
    wait(180);
    move_vel(120, aim_player(), 1.2fx, EASE_QUAD_IN);
    loop { wait(1000); }
}

